"""Client-side queue and reconnect replay for offline edits."""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from threading import Lock
from typing import Protocol

from models.record import ApplyResult, OfflineEdit


PRESERVES = "local creation order only"
STREAM_LINK = "offline.edits"


class OfflineEditTarget(Protocol):
    def apply_offline_edit(self, edit: OfflineEdit) -> ApplyResult: ...


@dataclass(frozen=True)
class SyncReport:
    attempted: int
    applied: int
    rejected: int
    remaining: int
    error: Exception | None = None

    @property
    def complete(self) -> bool:
        return self.error is None and self.remaining == 0


class OfflineEditQueue:
    """A FIFO queue that acknowledges only completed replay attempts."""

    def __init__(self) -> None:
        self._items: deque[OfflineEdit] = deque()
        self._lock = Lock()

    def enqueue(self, edit: OfflineEdit) -> None:
        with self._lock:
            self._items.append(edit)

    def pending(self) -> tuple[OfflineEdit, ...]:
        with self._lock:
            return tuple(self._items)

    def __len__(self) -> int:
        with self._lock:
            return len(self._items)

    def reconnect(self, target: OfflineEditTarget) -> SyncReport:
        """Replay the queue snapshot through the record model in FIFO order.

        Edits enqueued while a reconnect is running are outside the snapshot
        and remain for the next drain.  On a transport or model exception the
        failed edit and the entire later suffix stay queued.
        """

        snapshot = self.pending()
        attempted = applied = rejected = 0

        for edit in snapshot:
            attempted += 1
            try:
                result = target.apply_offline_edit(edit)
            except Exception as exc:  # the queue is the retry boundary
                return SyncReport(
                    attempted=attempted,
                    applied=applied,
                    rejected=rejected,
                    remaining=len(self),
                    error=exc,
                )

            if not result.acknowledged:
                return SyncReport(
                    attempted=attempted,
                    applied=applied,
                    rejected=rejected,
                    remaining=len(self),
                    error=RuntimeError("record model returned no acknowledgement"),
                )

            if not self._acknowledge_head(edit.edit_id):
                return SyncReport(
                    attempted=attempted,
                    applied=applied,
                    rejected=rejected,
                    remaining=len(self),
                    error=RuntimeError("offline edit queue changed during replay"),
                )

            if result.applied:
                applied += 1
            else:
                rejected += 1

        return SyncReport(
            attempted=attempted,
            applied=applied,
            rejected=rejected,
            remaining=len(self),
        )

    def _acknowledge_head(self, edit_id: str) -> bool:
        with self._lock:
            if not self._items or self._items[0].edit_id != edit_id:
                return False
            self._items.popleft()
            return True


def sync_on_reconnect(
    queue: OfflineEditQueue,
    record_model: OfflineEditTarget,
) -> SyncReport:
    """Application reconnect hook for the ``offline.edits`` stream."""

    return queue.reconnect(record_model)
