from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from enum import Enum
from typing import Callable, Mapping

from server.tombstones import TombstoneStore, as_utc


STREAM = "offline.edits"
STAMPED = "updated_at"


class EditOperation(str, Enum):
    CREATE = "create"
    UPDATE = "update"


class ApplyStatus(str, Enum):
    APPLIED = "applied"
    DUPLICATE = "duplicate"
    TOMBSTONED = "tombstoned"
    MISSING = "missing"


@dataclass(frozen=True)
class OfflineEdit:
    edit_id: str
    record_id: str
    changes: Mapping[str, object]
    created_at: datetime
    operation: EditOperation = EditOperation.UPDATE

    def __post_init__(self) -> None:
        object.__setattr__(self, "created_at", as_utc(self.created_at))
        object.__setattr__(self, "changes", dict(self.changes))
        if not self.edit_id:
            raise ValueError("edit_id is required for idempotent replay")
        if not self.record_id:
            raise ValueError("record_id is required")


@dataclass(frozen=True)
class Record:
    record_id: str
    values: Mapping[str, object] = field(default_factory=dict)
    updated_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))

    def __post_init__(self) -> None:
        object.__setattr__(self, "values", dict(self.values))
        object.__setattr__(self, "updated_at", as_utc(self.updated_at))


@dataclass(frozen=True)
class ApplyResult:
    edit_id: str
    status: ApplyStatus
    acknowledged: bool
    record: Record | None = None

    @property
    def applied(self) -> bool:
        return self.status is ApplyStatus.APPLIED


class RecordRepository:
    """Applies online and offline writes through one timestamping boundary."""

    def __init__(
        self,
        tombstones: TombstoneStore | None = None,
        clock: Callable[[], datetime] | None = None,
    ) -> None:
        self.tombstones = tombstones or TombstoneStore()
        self._clock = clock or (lambda: datetime.now(timezone.utc))
        self._records: dict[str, Record] = {}
        self._processed: dict[str, ApplyResult] = {}

    def put(self, record: Record) -> None:
        self._records[record.record_id] = record

    def get(self, record_id: str) -> Record | None:
        return self._records.get(record_id)

    def delete(self, record_id: str, deleted_at: datetime | None = None) -> None:
        when = as_utc(deleted_at or self._clock())
        self._records.pop(record_id, None)
        self.tombstones.record(record_id, when)

    def apply_offline_edit(self, edit: OfflineEdit) -> ApplyResult:
        """Apply one edit and return a durable acknowledgement.

        Policy rejections are acknowledged so the queue does not retry them
        forever.  Exceptions are not converted to acknowledgements; callers
        must retain the edit for a later reconnect attempt.
        """

        previous = self._processed.get(edit.edit_id)
        if previous is not None:
            return ApplyResult(
                edit_id=edit.edit_id,
                status=ApplyStatus.DUPLICATE,
                acknowledged=True,
                record=previous.record,
            )

        tombstone = self.tombstones.get(edit.record_id)
        if tombstone is not None and (
            edit.operation is not EditOperation.CREATE
            or edit.created_at <= tombstone.deleted_at
        ):
            return self._remember(edit, ApplyStatus.TOMBSTONED)

        current = self._records.get(edit.record_id)
        if current is None and edit.operation is not EditOperation.CREATE:
            return self._remember(edit, ApplyStatus.MISSING)

        now = as_utc(self._clock())
        values = dict(current.values) if current is not None else {}
        values.update(edit.changes)

        # A frozen or coarse clock must not reverse two locally ordered edits.
        if current is not None and now <= current.updated_at:
            now = current.updated_at + timedelta(microseconds=1)

        record = Record(record_id=edit.record_id, values=values, updated_at=now)
        self._records[edit.record_id] = record
        return self._remember(edit, ApplyStatus.APPLIED, record)

    def _remember(
        self,
        edit: OfflineEdit,
        status: ApplyStatus,
        record: Record | None = None,
    ) -> ApplyResult:
        result = ApplyResult(
            edit_id=edit.edit_id,
            status=status,
            acknowledged=True,
            record=record,
        )
        self._processed[edit.edit_id] = result
        return result
"""Deletion markers consulted while replaying offline edits."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone


TOMBSTONE_HOURS = 24
STREAM_REF = "offline.edits"


def as_utc(value: datetime) -> datetime:
    """Return an aware UTC timestamp, treating naive values as UTC."""

    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


@dataclass(frozen=True)
class Tombstone:
    record_id: str
    deleted_at: datetime

    def __post_init__(self) -> None:
        object.__setattr__(self, "deleted_at", as_utc(self.deleted_at))

    def is_active(self, now: datetime) -> bool:
        """The retention boundary is inclusive to avoid an expiry race."""

        age = as_utc(now) - self.deleted_at
        return age <= timedelta(hours=TOMBSTONE_HOURS)


class TombstoneStore:
    """Keeps deletion history used to prevent stale-edit resurrection.

    Expired markers are no longer *active* tombstones, but the deletion time is
    deliberately retained as a high-water mark.  Dropping that time after 24
    hours would allow a client that was offline longer than the retention
    window to recreate a deleted record during replay.
    """

    def __init__(self) -> None:
        self._items: dict[str, Tombstone] = {}

    def record(self, record_id: str, deleted_at: datetime) -> Tombstone:
        tombstone = Tombstone(record_id=record_id, deleted_at=deleted_at)
        current = self._items.get(record_id)
        if current is None or tombstone.deleted_at >= current.deleted_at:
            self._items[record_id] = tombstone
            return tombstone
        return current

    def get(self, record_id: str) -> Tombstone | None:
        return self._items.get(record_id)

    def is_active(self, record_id: str, now: datetime) -> bool:
        tombstone = self.get(record_id)
        return tombstone is not None and tombstone.is_active(now)
from datetime import datetime, timedelta, timezone
import unittest

from client.queue import OfflineEditQueue, sync_on_reconnect
from models.record import (
    ApplyResult,
    ApplyStatus,
    EditOperation,
    OfflineEdit,
    Record,
    RecordRepository,
)
from server.tombstones import TOMBSTONE_HOURS, TombstoneStore


UTC = timezone.utc


def edit(number, *, record_id="record-1", created_at=None, operation=EditOperation.UPDATE):
    return OfflineEdit(
        edit_id=f"edit-{number}",
        record_id=record_id,
        changes={"value": number},
        created_at=created_at or datetime(2026, 1, 1, tzinfo=UTC),
        operation=operation,
    )


class OfflineSyncTests(unittest.TestCase):
    def test_reconnect_replays_in_local_order_through_record_model(self):
        queue = OfflineEditQueue()
        for number in (1, 2, 3):
            queue.enqueue(edit(number))

        calls = []

        class Target:
            def apply_offline_edit(self, item):
                calls.append(item.edit_id)
                return ApplyResult(item.edit_id, ApplyStatus.APPLIED, True)

        report = sync_on_reconnect(queue, Target())

        self.assertEqual(calls, ["edit-1", "edit-2", "edit-3"])
        self.assertTrue(report.complete)
        self.assertEqual(report.applied, 3)

    def test_record_model_stamps_ordered_edits_monotonically(self):
        now = datetime(2026, 1, 2, tzinfo=UTC)
        repository = RecordRepository(clock=lambda: now)
        repository.put(Record("record-1", {"value": 0}, now - timedelta(days=1)))

        first = repository.apply_offline_edit(edit(1))
        second = repository.apply_offline_edit(edit(2))

        self.assertTrue(first.applied)
        self.assertTrue(second.applied)
        self.assertGreater(second.record.updated_at, first.record.updated_at)
        self.assertEqual(repository.get("record-1").values["value"], 2)

    def test_tombstone_blocks_stale_edit_at_retention_boundary_and_after(self):
        deleted_at = datetime(2026, 1, 2, tzinfo=UTC)
        for age in (
            timedelta(hours=TOMBSTONE_HOURS) - timedelta(microseconds=1),
            timedelta(hours=TOMBSTONE_HOURS),
            timedelta(hours=TOMBSTONE_HOURS) + timedelta(microseconds=1),
        ):
            tombstones = TombstoneStore()
            tombstones.record("record-1", deleted_at)
            repository = RecordRepository(
                tombstones=tombstones,
                clock=lambda: deleted_at + age,
            )

            result = repository.apply_offline_edit(
                edit(1, created_at=deleted_at - timedelta(minutes=1))
            )

            self.assertEqual(result.status, ApplyStatus.TOMBSTONED)
            self.assertIsNone(repository.get("record-1"))

    def test_failure_retains_failed_edit_and_suffix(self):
        queue = OfflineEditQueue()
        for number in (1, 2, 3):
            queue.enqueue(edit(number))

        class Target:
            def apply_offline_edit(self, item):
                if item.edit_id == "edit-2":
                    raise ConnectionError("offline again")
                return ApplyResult(item.edit_id, ApplyStatus.APPLIED, True)

        report = queue.reconnect(Target())

        self.assertIsInstance(report.error, ConnectionError)
        self.assertEqual([item.edit_id for item in queue.pending()], ["edit-2", "edit-3"])

    def test_retried_edit_is_idempotent(self):
        repository = RecordRepository(clock=lambda: datetime(2026, 1, 2, tzinfo=UTC))
        repository.put(Record("record-1", {"value": 0}, datetime(2026, 1, 1, tzinfo=UTC)))
        item = edit(1)

        first = repository.apply_offline_edit(item)
        duplicate = repository.apply_offline_edit(item)

        self.assertEqual(first.status, ApplyStatus.APPLIED)
        self.assertEqual(duplicate.status, ApplyStatus.DUPLICATE)
        self.assertEqual(duplicate.record, first.record)


if __name__ == "__main__":
    unittest.main()
